// Addon defines model for Addon.
type Addon struct {
	CreatedAt   *time.Time `json:"createdAt,omitempty"`
	Description string     `json:"description"`

	// FamilySlug The family the version belongs to
	//
	// Examples: extra-seats
	FamilySlug string  `json:"familySlug"`
	Id         *string `json:"id,omitempty"`

	// IsDefault The version the family resolves to. Only a PUBLISHED version.
	IsDefault bool `json:"isDefault"`

	// LifecycleState A DRAFT can be attached to try it; an ARCHIVED version stays on the instances holding it but cannot be attached again.
	LifecycleState AddonLifecycleState `json:"lifecycleState"`

	// MaxQuantity The largest quantity an instance can hold; unbounded when absent
	//
	// Examples: 10
	MaxQuantity *int32 `json:"maxQuantity,omitempty"`

	// Name Examples: Extra seats
	Name        string           `json:"name"`
	PricingType AddonPricingType `json:"pricingType"`

	// Slug The version's slug, unique in the organization
	//
	// Examples: extra-seats-v1
	Slug      string     `json:"slug"`
	UpdatedAt *time.Time `json:"updatedAt,omitempty"`

	// Version The version number in its family, assigned on create
	//
	// Examples: 1
	Version *int32 `json:"version,omitempty"`

	// VersionName Examples: Version - 1
	VersionName string `json:"versionName"`
}

// AddonLifecycleState A DRAFT can be attached to try it; an ARCHIVED version stays on the instances holding it but cannot be attached again.
